      "blocks": [
        {
          "kind": "p",
          "text": "Contoh berikut memakai angka atau bukti pada sumber. USD ditulis sebagai nama mata uang agar tidak tertukar dengan delimiter rumus."
        },
        {
          "kind": "solution-reveal",
          "title": "Kasus 1: Siklus GFI",
          "prompt": "GFI memegang barang 60 hari, menagih pelanggan 60 hari, dan membayar pemasok hari ke-40. Biaya barang 100.000 USD. Kapan dana perlu dibiayai? [hal. 566; PDF 608]",
          "revealLabel": "Lihat pembahasan",
          "blocks": [
            {
              "kind": "p",
              "text": "*Pembahasan:*"
            },
            {
              "kind": "formula",
              "text": "CCC=60+60-40=80\\ \\text{hari}",
              "note": "Persediaan dan piutang menambah waktu; utang pemasok mengurangi waktu. [hal. 566; PDF 608]"
            },
            {
              "kind": "p",
              "text": "Pembayaran pemasok terjadi pada hari ke-40, penjualan hari ke-60, dan penerimaan kas hari ke-120. Pendanaan 100.000 USD diperlukan selama 80 hari. Memperpendek CCC tetap perlu menjaga penjualan dan hubungan pemasok. [hal. 566; PDF 608]"
            }
          ]
        },
        {
          "kind": "solution-reveal",
          "title": "Kasus 2: Anggaran Juli Allied",
          "prompt": "Table 16.1: penjualan Mei 200, Juni 250, Juli 300 juta USD. Penerimaan 20% saat penjualan dengan diskon 2%, 70% bulan berikutnya, 10% dua bulan berikutnya. Pembayaran Juli 265, target kas 10. Hitung kebutuhan pada tabel. [hal. 571; PDF 613]",
          "revealLabel": "Lihat pembahasan",
          "blocks": [
            {
              "kind": "p",
              "text": "*Pembahasan:*"
            },
            {
              "kind": "formula",
              "text": "Collections=0.20(300)(0.98)+0.70(250)+0.10(200)=253.8",
              "note": "Satuan juta USD; tidak ada bad debt dalam asumsi dasar tabel. [hal. 571; PDF 613]"
            },
            {
              "kind": "p",
              "text": "Tabel buku membulatkan penerimaan menjadi 254. NCF Juli = 254 - 265 = minus 11 juta USD. Kumulatif NCF Juli juga minus 11, sehingga kebutuhan dibanding target 10 adalah 21 juta USD. [hal. 571; PDF 613]"
            },
            {
              "kind": "p",
              "text": "Jika menghitung tanpa pembulatan tabel, NCF minus 11,2 dan kebutuhan 21,2 juta USD. Nyatakan pilihan pembulatan agar hasil dapat diperiksa. Tabel memakai satuan juta tanpa desimal. Kebutuhan harian dapat melebihi saldo akhir bulan. [hal. 572; PDF 614]"
            }
          ]
        }
      ]
